/* Live updates by broadcast, not by watching tables (round 55, lib/realtime/own-topic.ts). The bell, a community's inbox, Home's orders and a plan set from /admin used to listen with Realtime postgres_changes, which makes the database check every listener's row level security on every change to those tables (Home listened to every order of every store). Now a trigger tells only the person concerned, on their own private broadcast topic `user:<their user id>`, that something changed and which row: `notification` { table, op, id, unread, community_id for a community's }, `order` { op, id, creator_id }, `plan` { op, creator_id }. Nothing else travels; the browser reads the row again through the API it already uses. `public.storelib_own_topic_ok(topic)` lets a signed in person join only their own topic (policy "storelib own topic read" on realtime.messages, read only: nobody can send on it from a browser). `public.storelib_tell_owner` sends the message and is the server's only (no browser role may call it); a failed send never fails the write that caused it. Triggers: `storelib_tell_owner` on user_notifications (a new row, and a row raised again unread), community_notifications (a new row), orders (a new or deleted order, and a change to its status, amount or refund) and creator_plan_overrides. Until it runs, and wherever realtime.messages or realtime.send is not there or this role may not add the policy, nothing is created and the app keeps listening the old way (it notices the join is refused). A table that is not there is skipped. No rows change. Safe to run again. */
CREATE OR REPLACE FUNCTION public.storelib_own_topic_ok(p_topic text) RETURNS boolean LANGUAGE sql STABLE SET search_path = '' AS $f$ SELECT (SELECT auth.uid()) IS NOT NULL AND p_topic = 'user:' || (SELECT auth.uid())::text $f$;
REVOKE ALL ON FUNCTION public.storelib_own_topic_ok(text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.storelib_own_topic_ok(text) TO authenticated, service_role;
CREATE OR REPLACE FUNCTION public.storelib_tell_owner(p_user uuid, p_event text, p_payload jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $f$ BEGIN IF p_user IS NULL OR p_event IS NULL THEN RETURN; END IF; PERFORM realtime.send(coalesce(p_payload, '{}'::jsonb), p_event, 'user:' || p_user::text, true); EXCEPTION WHEN OTHERS THEN RETURN; END $f$;
REVOKE ALL ON FUNCTION public.storelib_tell_owner(uuid, text, jsonb) FROM PUBLIC, anon, authenticated, service_role;
CREATE OR REPLACE FUNCTION public.storelib_tell_user_notification() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $f$ BEGIN PERFORM public.storelib_tell_owner(NEW.user_id, 'notification', jsonb_build_object('table', 'user_notifications', 'op', lower(TG_OP), 'id', NEW.id, 'unread', NEW.read_at IS NULL)); RETURN NULL; EXCEPTION WHEN OTHERS THEN RETURN NULL; END $f$;
CREATE OR REPLACE FUNCTION public.storelib_tell_community_notification() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $f$ BEGIN PERFORM public.storelib_tell_owner(NEW.user_id, 'notification', jsonb_build_object('table', 'community_notifications', 'op', lower(TG_OP), 'id', NEW.id, 'unread', NEW.read_at IS NULL, 'community_id', NEW.community_id)); RETURN NULL; EXCEPTION WHEN OTHERS THEN RETURN NULL; END $f$;
CREATE OR REPLACE FUNCTION public.storelib_tell_order() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $f$ DECLARE v_row jsonb; v_creator uuid; v_user uuid; BEGIN v_row := to_jsonb(CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END); v_creator := nullif(v_row ->> 'creator_id', '')::uuid; IF v_creator IS NULL AND nullif(v_row ->> 'product_id', '') IS NOT NULL THEN SELECT p.creator_id INTO v_creator FROM public.products p WHERE p.id = (v_row ->> 'product_id')::uuid; END IF; IF v_creator IS NULL THEN RETURN NULL; END IF; SELECT c.user_id INTO v_user FROM public.creators c WHERE c.id = v_creator; PERFORM public.storelib_tell_owner(v_user, 'order', jsonb_build_object('op', lower(TG_OP), 'id', v_row ->> 'id', 'creator_id', v_creator)); RETURN NULL; EXCEPTION WHEN OTHERS THEN RETURN NULL; END $f$;
CREATE OR REPLACE FUNCTION public.storelib_tell_plan() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $f$ DECLARE v_creator uuid; v_user uuid; BEGIN v_creator := CASE WHEN TG_OP = 'DELETE' THEN OLD.creator_id ELSE NEW.creator_id END; SELECT c.user_id INTO v_user FROM public.creators c WHERE c.id = v_creator; PERFORM public.storelib_tell_owner(v_user, 'plan', jsonb_build_object('op', lower(TG_OP), 'creator_id', v_creator)); RETURN NULL; EXCEPTION WHEN OTHERS THEN RETURN NULL; END $f$;
REVOKE ALL ON FUNCTION public.storelib_tell_user_notification() FROM PUBLIC, anon, authenticated, service_role;
REVOKE ALL ON FUNCTION public.storelib_tell_community_notification() FROM PUBLIC, anon, authenticated, service_role;
REVOKE ALL ON FUNCTION public.storelib_tell_order() FROM PUBLIC, anon, authenticated, service_role;
REVOKE ALL ON FUNCTION public.storelib_tell_plan() FROM PUBLIC, anon, authenticated, service_role;
DO $do$ DECLARE v_when text; BEGIN IF to_regclass('realtime.messages') IS NULL OR to_regprocedure('realtime.topic()') IS NULL OR to_regprocedure('realtime.send(jsonb,text,text,boolean)') IS NULL THEN RAISE NOTICE 'own topics: realtime.messages or realtime.send is not here, nothing is sent and the app keeps listening the old way.'; RETURN; END IF; BEGIN EXECUTE 'DROP POLICY IF EXISTS "storelib own topic read" ON realtime.messages'; EXECUTE 'CREATE POLICY "storelib own topic read" ON realtime.messages FOR SELECT TO authenticated USING (realtime.messages.extension = ''broadcast'' AND public.storelib_own_topic_ok(realtime.topic()))'; EXCEPTION WHEN insufficient_privilege THEN RAISE NOTICE 'own topics: this role may not add policies to realtime.messages, nothing is sent and the app keeps listening the old way.'; RETURN; END; IF to_regclass('public.user_notifications') IS NOT NULL THEN EXECUTE 'DROP TRIGGER IF EXISTS storelib_tell_owner ON public.user_notifications'; EXECUTE 'DROP TRIGGER IF EXISTS storelib_tell_owner_raised ON public.user_notifications'; EXECUTE 'CREATE TRIGGER storelib_tell_owner AFTER INSERT ON public.user_notifications FOR EACH ROW EXECUTE FUNCTION public.storelib_tell_user_notification()'; EXECUTE 'CREATE TRIGGER storelib_tell_owner_raised AFTER UPDATE ON public.user_notifications FOR EACH ROW WHEN (NEW.read_at IS NULL) EXECUTE FUNCTION public.storelib_tell_user_notification()'; END IF; IF to_regclass('public.community_notifications') IS NOT NULL THEN EXECUTE 'DROP TRIGGER IF EXISTS storelib_tell_owner ON public.community_notifications'; EXECUTE 'CREATE TRIGGER storelib_tell_owner AFTER INSERT ON public.community_notifications FOR EACH ROW EXECUTE FUNCTION public.storelib_tell_community_notification()'; END IF; IF to_regclass('public.orders') IS NOT NULL AND to_regclass('public.creators') IS NOT NULL THEN SELECT string_agg(format('OLD.%1$I IS DISTINCT FROM NEW.%1$I', c.column_name), ' OR ' ORDER BY c.column_name) INTO v_when FROM information_schema.columns c WHERE c.table_schema = 'public' AND c.table_name = 'orders' AND c.column_name IN ('status', 'amount_cents', 'refund_amount_cents', 'refunded_at', 'creator_id', 'product_id'); EXECUTE 'DROP TRIGGER IF EXISTS storelib_tell_owner ON public.orders'; EXECUTE 'DROP TRIGGER IF EXISTS storelib_tell_owner_changed ON public.orders'; EXECUTE 'CREATE TRIGGER storelib_tell_owner AFTER INSERT OR DELETE ON public.orders FOR EACH ROW EXECUTE FUNCTION public.storelib_tell_order()'; EXECUTE 'CREATE TRIGGER storelib_tell_owner_changed AFTER UPDATE ON public.orders FOR EACH ROW ' || CASE WHEN v_when IS NULL THEN '' ELSE 'WHEN (' || v_when || ') ' END || 'EXECUTE FUNCTION public.storelib_tell_order()'; END IF; IF to_regclass('public.creator_plan_overrides') IS NOT NULL AND to_regclass('public.creators') IS NOT NULL THEN EXECUTE 'DROP TRIGGER IF EXISTS storelib_tell_owner ON public.creator_plan_overrides'; EXECUTE 'CREATE TRIGGER storelib_tell_owner AFTER INSERT OR UPDATE OR DELETE ON public.creator_plan_overrides FOR EACH ROW EXECUTE FUNCTION public.storelib_tell_plan()'; END IF; END $do$;
notify pgrst, 'reload schema';
